local _, addon = ...
addon.localeData.enUS.texts = {
    FIREBALL = { name = "Fireball", ziel = { "Feel the heat, %s.", "*casts Fireball on %s.*", "%s, your armor is no substitute for fire resistance." }, gruppe = { "Feel the heat.", "*conjures Fireball.*", "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "The flame obeys my hand, not my temper.", "*closes a fist around a red-hot core of flame and hurls it forward.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    FROSTBOLT = { name = "Frostbolt", ziel = { "A chilly greeting, %s.", "*casts Frostbolt on %s.*", "%s, each step will grow heavier now." }, gruppe = { "A chilly greeting.", "*conjures Frostbolt.*", "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "Winter needs no invitation.", "*draws a jagged shard of ice from the damp air.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    ARCANE_MISSILES = { name = "Arcane Missiles", ziel = { "Arcane energies seek you, %s.", "*casts Arcane Missiles on %s.*", "%s, five thoughts, a single target." }, gruppe = { "Arcane energies seek you.", "*conjures Arcane Missiles.*", "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "The missiles will find their path through chaos.", "*splits a violet thread of light into seeking sparks.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    FIRE_BLAST = { name = "Fire Blast", ziel = { "One spark will do, %s!", "*casts Fire Blast on %s.*", "%s, this requires no lengthy lecture." }, gruppe = { "One spark will do!", "*conjures Fire Blast.*", "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "One instant is enough when the spark is placed well.", "*snaps a finger and ignites the air with a sharp crack.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    PYROBLAST = { name = "Pyroblast", ziel = { "Time for a proper firestorm, %s!", "*casts Pyroblast on %s.*", "%s, this incantation deserves some distance." }, gruppe = { "Time for a proper firestorm!", "*conjures Pyroblast.*", "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "Great flames demand a steady hand.", "*traces a broad circle of fire and compresses it into a roaring sphere.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    FLAMESTRIKE = { name = "Flamestrike", ziel = { "The ground itself shall burn!", "*casts Flamestrike on %s.*", "%s, mind where you stand." }, gruppe = { "The ground itself shall burn!", "*conjures Flamestrike.*", "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "The ground remembers every misplaced sigil.", "*draws a burning pattern beneath the enemies' feet.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    SCORCH = { name = "Scorch", ziel = { "Just a taste of fire, %s.", "*casts Scorch on %s.*", "%s, a brief lesson in applied heat." }, gruppe = { "Just a taste of fire.", "*conjures Scorch.*", "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "Not every flame needs to become an inferno.", "*brushes two fingers through the air, leaving a narrow trail of embers.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    BLIZZARD = { name = "Blizzard", ziel = { "Winter shows no mercy!", "*casts Blizzard on %s.*", "%s, you had better find warm shelter." }, gruppe = { "Winter shows no mercy!", "*conjures Blizzard.*", "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "When the sky falls silent, the snow speaks.", "*raises both arms and summons a swirl of snow and cutting ice.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    FROST_NOVA = { name = "Frost Nova", ziel = { "Not another step, %s!", "*casts Frost Nova on %s.*", "%s, your charge ends here." }, gruppe = { "Not another step!", "*conjures Frost Nova.*", "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "Cold draws a boundary no one can overlook.", "*presses a palm toward the ground and sends frost racing outward.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    CONE_OF_COLD = { name = "Cone of Cold", ziel = { "A breath of the north!", "*casts Cone of Cold on %s.*", "%s, winter air is coming your way." }, gruppe = { "A breath of the north!", "*conjures Cone of Cold.*", "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "One breath is enough to make close quarters unpleasant.", "*spreads the fingers and drives a wedge of freezing air forward.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    ICE_BARRIER = { name = "Ice Barrier", ziel = {  }, gruppe = { "Cold is my shield.", "*conjures Ice Barrier.*", "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "My shield is woven from patience and frost.", "*layers delicate crystals of ice around the body.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    ICE_BLOCK = { name = "Ice Block", ziel = {  }, gruppe = { "I am briefly unavailable.", "*conjures Ice Block.*", "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "Some attacks deserve no reply, only a pause.", "*closes the eyes as clear ice seals around the body.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    ARCANE_EXPLOSION = { name = "Arcane Explosion", ziel = { "Stand back, the magic is restless!", "*casts Arcane Explosion on %s.*", "%s, step out of my spell circle." }, gruppe = { "Stand back, the magic is restless!", "*conjures Arcane Explosion.*", "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "Distance is sometimes the wisest arcane discipline.", "*throws both arms apart, unleashing a ring of violet energy.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    COUNTERSPELL = { name = "Counterspell", ziel = { "Your incantation ends here, %s!", "*casts Counterspell on %s.*", "%s, your syllables are out of place." }, gruppe = { "Your incantation ends here!", "*conjures Counterspell.*", "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "A spell can shatter when a single syllable is stolen.", "*slices an opposing incantation in two with a pair of fingers.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    POLYMORPH = { name = "Polymorph", ziel = { "A little wool suits you, %s.", "*casts Polymorph on %s.*", "%s, you seemed considerably taller a moment ago." }, gruppe = { "A little wool suits you.", "*conjures Polymorph.*", "A woollier appearance might suit you.", "*sketches the outline of a sheep.*", "A little humility, four hooves and a great deal of wool.", "*shapes the outline of a sheep from light and folds it over the target.*", "Transformation is a precise art; the fleece is incidental.", "*checks the spell's outline for any unexpected horns.*", "A temporary change of shape can be wonderfully persuasive." } },
    BLINK = { name = "Blink", ziel = {  }, gruppe = { "Just a moment, I will be elsewhere.", "*conjures Blink.*", "The shortest route may bend through space.", "*folds a map into a glowing speck.*", "The shortest path is not always the visible one.", "*vanishes into a thin blue seam of light and reappears a heartbeat later.*", "I prefer to arrive with all my limbs accounted for.", "*checks the final coordinate with a fingertip before vanishing.*", "The world is very small from the right angle." } },
    SLOW_FALL = { name = "Slow Fall", ziel = { "Gravity can wait today.", "*casts Slow Fall on %s.*" }, gruppe = { "Gravity can wait today.", "*conjures Slow Fall.*", "The shortest route may bend through space.", "*folds a map into a glowing speck.*", "Gravity shall make an exception today.", "*traces a weightless arc beneath the boots.*", "I prefer to arrive with all my limbs accounted for.", "*checks the final coordinate with a fingertip before vanishing.*", "The world is very small from the right angle." } },
    EVOCATION = { name = "Evocation", ziel = {  }, gruppe = { "A moment to gather my thoughts and mana.", "*conjures Evocation.*", "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "Even great art occasionally needs a moment to breathe.", "*slowly draws scattered mana sparks back into both palms.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    ARCANE_INTELLECT = { name = "Arcane Intellect", ziel = { "A sharp mind is your finest weapon, %s.", "*casts Arcane Intellect on %s.*", "%s, may your mind be keener than your blade." }, gruppe = { "A sharp mind is your finest weapon.", "*conjures Arcane Intellect.*", "A keen mind is a useful gift.", "*passes on a softly shining glyph.*", "An alert mind is the most reliable talisman.", "*places a small luminous glyph beside the temple.*", "Strength of mind is best shared among trusted allies.", "*passes a faintly glowing symbol from palm to palm.*", "A single clear thought may save a company." } },
    ARCANE_BRILLIANCE = { name = "Arcane Brilliance", ziel = { "May our minds shine brighter!", "*casts Arcane Brilliance on %s.*", "%s, knowledge improves when shared." }, gruppe = { "May our minds shine brighter!", "*conjures Arcane Brilliance.*", "A keen mind is a useful gift.", "*passes on a softly shining glyph.*", "The wisest company thinks together.", "*spreads a web of bright runes over the allies.*", "Strength of mind is best shared among trusted allies.", "*passes a faintly glowing symbol from palm to palm.*", "A single clear thought may save a company." } },
    MANA_SHIELD = { name = "Mana Shield", ziel = {  }, gruppe = { "Mana into shelter, thought into steel.", "*conjures Mana Shield.*", "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "My thoughts are harder to pierce than my robes.", "*wraps flowing threads of mana around the shoulders.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    CONJURE_FOOD = { name = "Conjure Food", ziel = {  }, gruppe = { "A little magic against hunger.", "*conjures Conjure Food.*", "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "Good magic occasionally satisfies hunger as well.", "*opens both hands and produces a pleasantly fragrant snack.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    CONJURE_WATER = { name = "Conjure Water", ziel = {  }, gruppe = { "Fresh water, drawn from pure magic.", "*conjures Conjure Water.*", "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "Drink. Arcane studies are thirsty work.", "*catches a drop of light and turns it into clear water.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    CREATE_MANA_GEM = { name = "Conjure Mana Gem", ziel = {  }, gruppe = { "A little reserve for dire moments.", "*conjures Conjure Mana Gem.*", "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "A small reserve for a large problem.", "*presses flickering mana into a cool, glowing gem.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    PORTAL = { name = "Portal", ziel = {  }, gruppe = { "Mind your limbs when stepping through.", "*conjures Portal.*", "Please keep your limbs inside the portal.", "*double-checks the destination coordinates.*", "Anyone stepping through should trust the destination circle.", "*carefully opens a round fold in the fabric of space.*", "No shoving. Dimensional geometry is unforgiving.", "*steadies the trembling rim of a circular gateway.*", "A good portal begins with sound coordinates." } },
    TELEPORT = { name = "Teleport", ziel = {  }, gruppe = { "I shall take the shortcut through space.", "*conjures Teleport.*", "The shortest route may bend through space.", "*folds a map into a glowing speck.*", "One step, one wrong coordinate, a thousand miles astray.", "*traces the destination rune and dissolves into a whirl of light.*", "I prefer to arrive with all my limbs accounted for.", "*checks the final coordinate with a fingertip before vanishing.*", "The world is very small from the right angle." } },
    REMOVE_LESSER_CURSE = { name = "Remove Lesser Curse", ziel = { "This curse has no place here, %s.", "*casts Remove Lesser Curse on %s.*", "%s, this curse has clung on long enough." }, gruppe = { "This curse has no place here.", "*conjures Remove Lesser Curse.*", "There is a formula for almost everything.", "*turns to the right page of a spellbook.*", "No binding lasts forever when you know its knots.", "*uses a shining rune to lift a shadow from a shoulder.*", "Even a modest enchantment deserves careful preparation.", "*compares two worn pages before choosing the correct rune.*", "There is no such thing as a trivial spell to a careless mage." } },
    DETECT_MAGIC = { name = "Detect Magic", ziel = { "Let us see what secrets you carry, %s.", "*casts Detect Magic on %s.*", "%s, your aura reveals more than your words." }, gruppe = { "Let us see what secrets you carry.", "*conjures Detect Magic.*", "There is a formula for almost everything.", "*turns to the right page of a spellbook.*", "Hidden currents always leave a trace.", "*holds a shimmering sigil to the light and studies its response.*", "Even a modest enchantment deserves careful preparation.", "*compares two worn pages before choosing the correct rune.*", "There is no such thing as a trivial spell to a careless mage." } },
    DAMPEN_MAGIC = { name = "Dampen Magic", ziel = { "%s, a little less magical noise will do you good.", "Not every power needs to speak at full volume.", "*lays a silvery veil over the pulsing mana currents.*" }, gruppe = { "A keen mind is a useful gift.", "*passes on a softly shining glyph.*", "Not every power needs to speak at full volume.", "*lays a silvery veil over the pulsing mana currents.*", "Strength of mind is best shared among trusted allies.", "*passes a faintly glowing symbol from palm to palm.*", "A single clear thought may save a company." } },
    AMPLIFY_MAGIC = { name = "Amplify Magic", ziel = { "%s, I open your senses to stronger currents.", "More power is a gift only if you can guide it.", "*widens the glowing circle around an ally with a measured gesture.*" }, gruppe = { "A keen mind is a useful gift.", "*passes on a softly shining glyph.*", "More power is a gift only if you can guide it.", "*widens the glowing circle around an ally with a measured gesture.*", "Strength of mind is best shared among trusted allies.", "*passes a faintly glowing symbol from palm to palm.*", "A single clear thought may save a company." } },
    FROST_ARMOR = { name = "Frost Armor", ziel = {  }, gruppe = { "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "A cool head deserves armor to match.", "*draws a shimmering frost rim around shoulders and arms.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    ICE_ARMOR = { name = "Ice Armor", ziel = {  }, gruppe = { "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "Anyone who touches me shall greet winter first.", "*grows hard plates of ice across the robe like scales.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    MAGE_ARMOR = { name = "Mage Armor", ziel = {  }, gruppe = { "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "Arcane discipline begins just beneath my robes.", "*kindles a barely visible layer of protective glyphs.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    FIRE_WARD = { name = "Fire Ward", ziel = {  }, gruppe = { "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "Fire recognizes fire, but not every flame may pass.", "*closes a golden ring of fire into a warding seal.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    FROST_WARD = { name = "Frost Ward", ziel = {  }, gruppe = { "Caution is an art, not a weakness.", "*draws a shimmering protective circle.*", "Winter knocks. My answer is already prepared.", "*raises a transparent circle of crystal against the freezing air.*", "A small ward placed correctly outlasts a reckless defense.", "*tests the edge of an invisible protective layer.*", "The best protection is ready before the first blow." } },
    ARCANE_BLAST = { name = "Arcane Blast", ziel = { "%s, there is no arguing away this energy.", "Raw power needs no flame to leave its mark.", "*drives a dense surge of violet light forward.*" }, gruppe = { "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "Raw power needs no flame to leave its mark.", "*drives a dense surge of violet light forward.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    ARCANE_WRATH = { name = "Arcane Wrath", ziel = { "%s, my patience was your final layer of protection.", "The arcane answers foolishness with emphasis.", "*twists two floating sigils until a bright pulse bursts from between them.*" }, gruppe = { "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "The arcane answers foolishness with emphasis.", "*twists two floating sigils until a bright pulse bursts from between them.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    ARCANE_POWER = { name = "Arcane Power", ziel = {  }, gruppe = { "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "Now theory may show what it is truly worth.", "*opens both hands as bright rings of runes spin faster together.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    PRESENCE_OF_MIND = { name = "Presence of Mind", ziel = {  }, gruppe = { "The equation is elegant. The consequences less so.", "*aligns several violet glyphs.*", "Some thoughts move faster than the tongue.", "*pauses as if every possible path has suddenly become visible.*", "Every rune is a decision, and every decision has a price.", "*balances two flickering symbols before joining them in midair.*", "I trust a tested sigil more than a bold guess." } },
    BLAST_WAVE = { name = "Blast Wave", ziel = { "%s, you are standing too close to my center.", "When the air strikes back, distance is a sensible choice.", "*claps both palms together, sending a scorching shock wave outward.*" }, gruppe = { "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "When the air strikes back, distance is a sensible choice.", "*claps both palms together, sending a scorching shock wave outward.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    COMBUSTION = { name = "Combustion", ziel = {  }, gruppe = { "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "Every ember shall give its last spark today.", "*draws the heat of the surroundings into a single flickering flame.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    FROSTFIRE_BOLT = { name = "Frostfire Bolt", ziel = { "%s, choose quickly between frost and flame.", "A contradiction? Only to a poor mage.", "*weaves blue shards of ice through red strands of flame into a single bolt.*" }, gruppe = { "There is a formula for almost everything.", "*turns to the right page of a spellbook.*", "A contradiction? Only to a poor mage.", "*weaves blue shards of ice through red strands of flame into a single bolt.*", "Even a modest enchantment deserves careful preparation.", "*compares two worn pages before choosing the correct rune.*", "There is no such thing as a trivial spell to a careless mage." } },
    FELFIRE = { name = "Felfire", ziel = { "%s, even this alien flame answers to a well-drawn seal.", "Green fire demands greater care, not less thought.", "*contains a restless green flame within a narrow ring of runes.*" }, gruppe = { "Fire has always been an honest negotiator.", "*spins a ribbon of amber sparks.*", "Green fire demands greater care, not less thought.", "*contains a restless green flame within a narrow ring of runes.*", "Flame is a craft, not an excuse to lose control.", "*draws a glowing seam through the air with the edge of a palm.*", "A careful spark can change the course of a battle." } },
    ICE_LANCE = { name = "Ice Lance", ziel = { "%s, a single shard is answer enough.", "Ice need not be large to be sharp.", "*presses glittering frost into a needle-thin lance.*" }, gruppe = { "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "Ice need not be large to be sharp.", "*presses glittering frost into a needle-thin lance.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    FROST_BLAST = { name = "Frost Blast", ziel = { "%s, this winter comes without warning.", "Cold in a single, relentless heartbeat.", "*unleashes a violent burst of frost from an open fist.*" }, gruppe = { "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "Cold in a single, relentless heartbeat.", "*unleashes a violent burst of frost from an open fist.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    COLD_SNAP = { name = "Cold Snap", ziel = {  }, gruppe = { "Even the air holds its breath.", "*draws a ring of tiny ice crystals.*", "Time is just another variable in the art of frost.", "*breaks a floating snowflake and rearranges the frost sigils.*", "The finest frost is made with patience, not haste.", "*lets snowflakes settle into a perfectly ordered crystal.*", "Cold teaches an excellent lesson in keeping one's distance." } },
    CONJURE_MANA_AGATE = { name = "Conjure Mana Agate", ziel = {  }, gruppe = { "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "An agate small enough for a pocket and strong enough for a rescue.", "*pours a narrow stream of mana into a forming agate.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    CONJURE_MANA_JADE = { name = "Conjure Mana Jade", ziel = {  }, gruppe = { "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "Jade stores magic almost as patiently as a scholar.", "*settles green light into a smoothly polished mana gem.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    CONJURE_MANA_CITRINE = { name = "Conjure Mana Citrine", ziel = {  }, gruppe = { "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "A little golden sunlight for the hours when strength runs low.", "*forms a warmly glowing citrine from golden sparks.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    CONJURE_MANA_RUBY = { name = "Conjure Mana Ruby", ziel = {  }, gruppe = { "A respectable meal is high magic too.", "*shakes sparks from a sleeve.*", "This ruby has held more mana than some librarians have read about.", "*seals deep crimson streams of mana inside a glittering ruby.*", "Shaping mana into something useful is a practical kind of elegance.", "*weighs the freshly conjured object on an open palm.*", "The trick is making the result last longer than the applause." } },
    POLYMORPH_COW = { name = "Polymorph: Cow", ziel = { "%s, I hope you have nothing against cowbells.", "Four legs and plenty of grass for you today.", "*traces a cow's outline in softly glowing runes.*" }, gruppe = { "A woollier appearance might suit you.", "*sketches the outline of a sheep.*", "Four legs and plenty of grass for you today.", "*traces a cow's outline in softly glowing runes.*", "Transformation is a precise art; the fleece is incidental.", "*checks the spell's outline for any unexpected horns.*", "A temporary change of shape can be wonderfully persuasive." } },
    COMPREHEND_SCROLL = { name = "Comprehend Scroll", ziel = {  }, gruppe = { "There is a formula for almost everything.", "*turns to the right page of a spellbook.*", "Some scrolls yield their meaning only to patient eyes.", "*holds a scroll to the light and unravels its sealed markings.*", "Even a modest enchantment deserves careful preparation.", "*compares two worn pages before choosing the correct rune.*", "There is no such thing as a trivial spell to a careless mage." } },
    STUDY = { name = "Study", ziel = {  }, gruppe = { "There is a formula for almost everything.", "*turns to the right page of a spellbook.*", "Those who only cast and never read remain apprentices.", "*smooths a note written in the margin of an ancient tome.*", "Even a modest enchantment deserves careful preparation.", "*compares two worn pages before choosing the correct rune.*", "There is no such thing as a trivial spell to a careless mage." } },
    TELEPORT_STORMWIND = { name = "Teleport: STORMWIND", ziel = {  }, gruppe = { "The shortest route may bend through space.", "*folds a map into a glowing speck.*", "Stormwind is only one well-placed rune away.", "*folds the image of white towers into a spinning point of light.*", "I prefer to arrive with all my limbs accounted for.", "*checks the final coordinate with a fingertip before vanishing.*", "The world is very small from the right angle." } },
    PORTAL_STORMWIND = { name = "Portal: STORMWIND", ziel = {  }, gruppe = { "Please keep your limbs inside the portal.", "*double-checks the destination coordinates.*", "A clear road to Stormwind's gates. One at a time, please.", "*stretches a blue gateway framed by the city's walls.*", "No shoving. Dimensional geometry is unforgiving.", "*steadies the trembling rim of a circular gateway.*", "A good portal begins with sound coordinates." } },
